#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct StockLaunch {
    shared_closure_ids: Vec<String>,
    python_environment: PythonEnvironment,
    program: String,
    args: Vec<String>,
    environment: BTreeMap<String, String>,
    current_dir: String,
    record_closures: Vec<RecordClosure>,
    embedded_files: Vec<EmbeddedFile>,
    metadata_overlays: Vec<MetadataOverlay>,
}

impl StockLaunch {
    fn validate(
        &self,
        manifest: &StockDistributionManifest,
        identity_components: &[accuracy::EvaluationIdentityComponent],
    ) -> Result<()> {
        ensure!(
            !self.shared_closure_ids.is_empty()
                && !self.record_closures.is_empty()
                && !self.embedded_files.is_empty(),
            "stock launch closure is incomplete"
        );
        let mut shared = BTreeSet::new();
        for id in &self.shared_closure_ids {
            ensure!(
                manifest.shared_closures.contains_key(id) && shared.insert(id.clone()),
                "stock launch references unknown or duplicate shared closure {id:?}"
            );
        }
        self.python_environment.validate()?;
        ensure!(
            self.program == PROGRAM && self.current_dir == CURRENT_DIR,
            "stock worker program/current directory drifted"
        );
        ensure!(
            !self.args.is_empty()
                && self.args.iter().all(|value| !value.contains('\0'))
                && self.environment.iter().all(|(key, value)| !key.is_empty()
                    && !key.contains('=')
                    && !value.contains('\0')),
            "stock worker argv/environment is invalid"
        );
        for key in STAGING_ENVIRONMENT_DIRECTORIES {
            let value = self
                .environment
                .get(*key)
                .ok_or_else(|| anyhow!("stock worker environment omitted {key}"))?;
            staging_environment_relative(value, key)?;
        }
        let mut records = BTreeSet::new();
        for closure in &self.record_closures {
            closure.validate()?;
            ensure!(
                records.insert(normalize_distribution_name(&closure.distribution)),
                "duplicate RECORD closure for {:?}",
                closure.distribution
            );
        }
        let mut embedded_destinations = BTreeSet::new();
        for file in &self.embedded_files {
            file.validate()?;
            ensure!(
                embedded_destinations.insert(file.destination.clone()),
                "duplicate embedded launch destination {:?}",
                file.destination
            );
        }
        let mut overlay_distributions = BTreeSet::new();
        for overlay in &self.metadata_overlays {
            overlay.validate(
                &self.record_closures,
                &self.embedded_files,
                identity_components,
            )?;
            ensure!(
                overlay_distributions.insert(normalize_distribution_name(&overlay.distribution)),
                "duplicate source overlay for {:?}",
                overlay.distribution
            );
        }
        let source_identity_components = identity_components
            .iter()
            .filter(|component| records.contains(&normalize_distribution_name(&component.name)))
            .map(|component| normalize_distribution_name(&component.name))
            .collect::<BTreeSet<_>>();
        ensure!(
            overlay_distributions == source_identity_components,
            "source overlays and identity components did not form the same exact package set"
        );
        Ok(())
    }
}

fn staging_environment_relative(value: &str, key: &str) -> Result<PathBuf> {
    let relative = value
        .strip_prefix("/staging/")
        .ok_or_else(|| anyhow!("stock worker {key} must be contained under /staging"))?;
    strict_relative_path(relative, &format!("stock worker {key}"))
}

fn prepare_staging_environment(staging: &Path, launch: &StockLaunch) -> Result<()> {
    let staging = staging
        .canonicalize()
        .with_context(|| format!("canonicalizing evaluator staging {}", staging.display()))?;
    for key in STAGING_ENVIRONMENT_DIRECTORIES {
        let value = launch
            .environment
            .get(*key)
            .ok_or_else(|| anyhow!("stock worker environment omitted {key}"))?;
        let directory = staging.join(staging_environment_relative(value, key)?);
        create_secure_directories(&staging, &directory)?;
        set_file_mode(&directory, 0o700)?;
    }
    Ok(())
}

