#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct MetadataOverlay {
    policy_id: String,
    distribution: String,
    version: String,
    upstream_record_sha256: String,
    omitted_paths: Vec<String>,
    base_source: BaseSourceIdentity,
    overlay_policy: String,
    overlays: Vec<OrderedSourceOverlay>,
    effective_source_tree_sha256: String,
    effective_source_tree_digest_policy: String,
    replacement_files: Vec<EmbeddedFile>,
}

impl MetadataOverlay {
    fn validate(
        &self,
        closures: &[RecordClosure],
        embedded_files: &[EmbeddedFile],
        identity_components: &[accuracy::EvaluationIdentityComponent],
    ) -> Result<()> {
        ensure!(
            self.policy_id == SOURCE_OVERLAY_MANIFEST_POLICY,
            "unknown evaluator metadata overlay policy {:?}",
            self.policy_id
        );
        ensure!(
            self.overlay_policy == SOURCE_OVERLAY_POLICY
                && self.base_source.digest_policy == SOURCE_TREE_DIGEST_POLICY
                && self.effective_source_tree_digest_policy == SOURCE_TREE_DIGEST_POLICY,
            "source overlay digest/application policy drifted"
        );
        ensure!(
            !self.distribution.trim().is_empty()
                && self.distribution.trim() == self.distribution
                && !self.version.trim().is_empty()
                && self.version.trim() == self.version,
            "source overlay distribution identity is invalid"
        );
        validate_sha256(&self.upstream_record_sha256, "overlay upstream RECORD")?;
        validate_source_commit(&self.base_source.commit, "overlay base commit")?;
        validate_sha256(
            &self.base_source.source_tree_sha256,
            "overlay base source tree",
        )?;
        validate_sha256(
            &self.effective_source_tree_sha256,
            "overlay effective source tree",
        )?;
        let closure = closures
            .iter()
            .find(|closure| {
                normalize_distribution_name(&closure.distribution)
                    == normalize_distribution_name(&self.distribution)
                    && closure.version == self.version
            })
            .ok_or_else(|| anyhow!("metadata overlay has no matching RECORD closure"))?;
        ensure!(
            closure.record_sha256 == self.upstream_record_sha256
                && closure.omitted_paths == self.omitted_paths,
            "metadata overlay RECORD/omission policy drifted"
        );
        ensure_strict_utf8_order(&self.omitted_paths, "overlay omitted paths")?;
        let dist_info = dist_info_prefix(&self.distribution, &self.version);
        let required_omissions = ["METADATA", "RECORD", "direct_url.json"]
            .into_iter()
            .map(|name| format!("{dist_info}/{name}"))
            .collect::<BTreeSet<_>>();
        let actual_omissions = self.omitted_paths.iter().cloned().collect::<BTreeSet<_>>();
        ensure!(
            required_omissions.is_subset(&actual_omissions),
            "metadata overlay omitted-path set is incomplete"
        );
        let import_package = self.distribution.replace('-', "_");
        let identity = identity_components
            .iter()
            .find(|component| {
                normalize_distribution_name(&component.name)
                    == normalize_distribution_name(&import_package)
                    && component.version == self.version
            })
            .ok_or_else(|| anyhow!("source overlay has no matching identity component"))?;

        ensure_strict_utf8_order(
            &self.base_source.excluded_relative_paths,
            "base-source exclusions",
        )?;
        for excluded in &self.base_source.excluded_relative_paths {
            validate_semantic_relative_path(excluded, "base-source exclusion")?;
        }
        let mut restored_paths = BTreeSet::new();
        let mut prior_restored = None;
        for restored in &self.base_source.restored_files {
            validate_semantic_relative_path(&restored.relative_path, "restored source path")?;
            validate_sha256(&restored.artifact_content_sha256, "restored source digest")?;
            ensure_utf8_after(
                prior_restored,
                &restored.relative_path,
                "restored source paths",
            )?;
            prior_restored = Some(restored.relative_path.as_str());
            ensure!(
                restored_paths.insert(restored.relative_path.clone()),
                "duplicate restored source path"
            );
        }

        let mut overlay_ids = BTreeSet::new();
        let mut target_paths = BTreeSet::new();
        for (ordinal, overlay) in self.overlays.iter().enumerate() {
            ensure!(
                overlay.ordinal == ordinal,
                "source overlay ordinals must be contiguous and ordered"
            );
            validate_open_manifest_id(&overlay.overlay_id, "source overlay ID")?;
            ensure!(
                overlay_ids.insert(overlay.overlay_id.clone()),
                "duplicate source overlay ID {:?}",
                overlay.overlay_id
            );
            let resource = strict_relative_path(&overlay.resource, "source overlay resource")?;
            ensure!(
                resource.extension().and_then(|value| value.to_str()) == Some("patch"),
                "source overlay resource must be a .patch"
            );
            validate_sha256(
                &overlay.artifact_content_sha256,
                "source overlay resource digest",
            )?;
            ensure!(!overlay.targets.is_empty(), "source overlay has no targets");
            let expected_resource = format!(
                "src/aiperf/accuracy/evaluation/source_overlays/{}",
                overlay.resource
            );
            let expected_destination = format!(
                "{SITE_PACKAGES_DESTINATION}/aiperf/accuracy/evaluation/source_overlays/{}",
                overlay.resource
            );
            let embedded = embedded_files
                .iter()
                .find(|file| file.destination == expected_destination)
                .ok_or_else(|| anyhow!("source overlay resource is absent from worker closure"))?;
            ensure!(
                !embedded.executable
                    && embedded.resource == expected_resource
                    && embedded.artifact_content_sha256 == overlay.artifact_content_sha256,
                "source overlay resource identity drifted"
            );
            let mut prior_target = None;
            for target in &overlay.targets {
                validate_semantic_relative_path(&target.relative_path, "source overlay target")?;
                ensure_utf8_after(
                    prior_target,
                    &target.relative_path,
                    "source overlay targets",
                )?;
                prior_target = Some(target.relative_path.as_str());
                ensure!(
                    target_paths.insert(target.relative_path.clone()),
                    "source overlays target the same path more than once"
                );
                if let Some(base) = &target.base_content_sha256 {
                    validate_sha256(base, "source overlay base-content digest")?;
                }
                validate_sha256(
                    &target.effective_content_sha256,
                    "source overlay effective-content digest",
                )?;
                let record_path = format!("{import_package}/{}", target.relative_path);
                ensure!(
                    actual_omissions.contains(&record_path) == target.base_content_sha256.is_some(),
                    "source overlay target omission/base identity drifted"
                );
            }
        }
        ensure!(
            restored_paths.is_disjoint(&target_paths),
            "restored base files and overlay targets overlap"
        );
        let exclusions = self
            .base_source
            .excluded_relative_paths
            .iter()
            .cloned()
            .collect::<BTreeSet<_>>();
        ensure!(
            exclusions.is_disjoint(&restored_paths) && exclusions.is_disjoint(&target_paths),
            "source exclusions overlap restored files or overlay targets"
        );

        let mut allowed_omissions = required_omissions.clone();
        allowed_omissions.insert(format!("{dist_info}/entry_points.txt"));
        allowed_omissions.extend(
            self.overlays
                .iter()
                .flat_map(|overlay| &overlay.targets)
                .filter(|target| target.base_content_sha256.is_some())
                .map(|target| format!("{import_package}/{}", target.relative_path)),
        );
        ensure!(
            actual_omissions.is_subset(&allowed_omissions),
            "source overlay omitted an undeclared upstream path"
        );

        let mut required_replacements = ["METADATA", "RECORD", "aiperf_source_attestation.json"]
            .into_iter()
            .map(|name| format!("runtime/lib/python3.12/site-packages/{dist_info}/{name}"))
            .collect::<BTreeSet<_>>();
        required_replacements.extend(
            self.overlays
                .iter()
                .flat_map(|overlay| &overlay.targets)
                .map(|target| {
                    format!(
                        "{SITE_PACKAGES_DESTINATION}/{import_package}/{}",
                        target.relative_path
                    )
                }),
        );
        required_replacements.extend(self.base_source.restored_files.iter().map(|restored| {
            format!(
                "{SITE_PACKAGES_DESTINATION}/{import_package}/{}",
                restored.relative_path
            )
        }));
        let actual_replacements = self
            .replacement_files
            .iter()
            .map(|file| file.destination.clone())
            .collect::<BTreeSet<_>>();
        ensure!(
            actual_replacements == required_replacements
                && self.replacement_files.len() == required_replacements.len(),
            "metadata overlay replacement image drifted"
        );
        for file in &self.replacement_files {
            ensure!(
                !file.executable
                    && file.resource.starts_with("generated://source-overlay/")
                    && file
                        .resource
                        .strip_prefix("generated://source-overlay/")
                        .and_then(|relative| relative.split_once('/'))
                        .is_some_and(|(distribution, _)| {
                            normalize_distribution_name(distribution)
                                == normalize_distribution_name(&self.distribution)
                        }),
                "source overlay replacement was not generated non-executable content"
            );
            file.validate()?;
        }
        let source_distribution_identities = self
            .replacement_files
            .iter()
            .map(|file| {
                file.resource
                    .strip_prefix("generated://source-overlay/")
                    .and_then(|relative| relative.split_once('/'))
                    .map(|(distribution, _)| distribution)
                    .ok_or_else(|| anyhow!("source overlay replacement resource is malformed"))
            })
            .collect::<Result<BTreeSet<_>>>()?;
        ensure!(
            source_distribution_identities.len() == 1,
            "source overlay replacement resources named multiple source identities"
        );
        self.validate_replacement_digests(&import_package, &dist_info)?;
        self.validate_attestation_bytes(&dist_info)?;
        self.validate_identity_component(identity)?;
        Ok(())
    }

    fn source_distribution_identity(&self) -> Result<&str> {
        self.replacement_files
            .first()
            .and_then(|file| {
                file.resource
                    .strip_prefix("generated://source-overlay/")
                    .and_then(|relative| relative.split_once('/'))
                    .map(|(distribution, _)| distribution)
            })
            .ok_or_else(|| anyhow!("source overlay replacement resource is malformed"))
    }

    fn validate_replacement_digests(&self, import_package: &str, dist_info: &str) -> Result<()> {
        for restored in &self.base_source.restored_files {
            let destination = format!(
                "{SITE_PACKAGES_DESTINATION}/{import_package}/{}",
                restored.relative_path
            );
            ensure!(
                replacement_file(&self.replacement_files, &destination).is_some_and(|file| file
                    .artifact_content_sha256
                    == restored.artifact_content_sha256),
                "restored source replacement digest drifted"
            );
        }
        for target in self.overlays.iter().flat_map(|overlay| &overlay.targets) {
            let destination = format!(
                "{SITE_PACKAGES_DESTINATION}/{import_package}/{}",
                target.relative_path
            );
            ensure!(
                replacement_file(&self.replacement_files, &destination).is_some_and(|file| {
                    file.artifact_content_sha256 == target.effective_content_sha256
                }),
                "source overlay target replacement digest drifted"
            );
        }
        ensure!(
            replacement_file(
                &self.replacement_files,
                &format!("{SITE_PACKAGES_DESTINATION}/{dist_info}/METADATA")
            )
            .is_some(),
            "source overlay omitted rebuilt METADATA"
        );
        Ok(())
    }

    fn validate_attestation_bytes(&self, dist_info: &str) -> Result<()> {
        let destination =
            format!("{SITE_PACKAGES_DESTINATION}/{dist_info}/aiperf_source_attestation.json");
        let file = replacement_file(&self.replacement_files, &destination)
            .ok_or_else(|| anyhow!("source overlay omitted source attestation"))?;
        let actual = decode_embedded(file)?;
        let value = serde_json::json!({
            "format": SOURCE_ATTESTATION_FORMAT,
            "distribution": self.source_distribution_identity()?,
            "version": self.version,
            "base": self.base_source,
            "overlay_policy": self.overlay_policy,
            "overlays": self.overlays,
            "effective_source_tree_sha256": self.effective_source_tree_sha256,
            "effective_source_tree_digest_policy": self.effective_source_tree_digest_policy,
        });
        let expected = accuracy::CanonicalJson::new(value)
            .map_err(|error| anyhow!(error.to_string()))?
            .to_bytes();
        ensure!(
            actual == expected,
            "source attestation bytes did not exactly match manifest evidence"
        );
        Ok(())
    }

    fn validate_identity_component(
        &self,
        identity: &accuracy::EvaluationIdentityComponent,
    ) -> Result<()> {
        ensure!(
            identity.source_sha256 == self.effective_source_tree_sha256,
            "effective source tree and identity component drifted"
        );
        if self.overlays.is_empty() {
            ensure!(
                identity.source_commit.is_none()
                    && identity.base_source_sha256.is_none()
                    && identity.overlay_policy.is_none()
                    && identity.overlays.is_empty(),
                "non-overlaid source component declared overlay identity"
            );
        } else {
            ensure!(
                identity.source_commit.as_deref() == Some(self.base_source.commit.as_str())
                    && identity.base_source_sha256.as_deref()
                        == Some(self.base_source.source_tree_sha256.as_str())
                    && identity.overlay_policy.as_deref() == Some(SOURCE_OVERLAY_POLICY)
                    && identity.overlays.len() == self.overlays.len()
                    && identity
                        .overlays
                        .iter()
                        .zip(&self.overlays)
                        .all(|(identity, overlay)| {
                            identity.overlay_id == overlay.overlay_id
                                && identity.artifact_content_sha256
                                    == overlay.artifact_content_sha256
                        }),
                "source overlay identity component drifted from ordered evidence"
            );
        }
        Ok(())
    }
}

fn replacement_file<'a>(files: &'a [EmbeddedFile], destination: &str) -> Option<&'a EmbeddedFile> {
    files.iter().find(|file| file.destination == destination)
}

fn dist_info_prefix(distribution: &str, version: &str) -> String {
    format!("{}-{version}.dist-info", distribution.replace('-', "_"))
}

#[derive(Clone)]
enum MaterializationSource {
    Path(PathBuf),
    Bytes(Arc<[u8]>),
}

#[derive(Clone)]
struct ResolvedFile {
    source: MaterializationSource,
    digest: String,
    executable: bool,
}

struct ResolvedLaunchClosure {
    files: BTreeMap<String, ResolvedFile>,
}

impl ResolvedLaunchClosure {
    fn resolve(
        manifest: &StockDistributionManifest,
        distribution: &StockDistribution,
        resolver: &dyn StockClosureSourceResolver,
    ) -> Result<Self> {
        let mut files = BTreeMap::new();
        for closure_id in &distribution.launch.shared_closure_ids {
            let closure = manifest
                .shared_closures
                .get(closure_id)
                .ok_or_else(|| anyhow!("missing shared closure {closure_id:?}"))?;
            let source_root = match &closure.resolver {
                SharedClosureResolver::PythonRuntimeRoot(runtime) => {
                    resolver.python_runtime_root(runtime)?
                }
                SharedClosureResolver::SystemRoot(system) => resolver.system_root(system)?,
            };
            for file in &closure.files {
                let source = source_root.join(strict_relative_path(
                    &file.source_relative_path,
                    "shared source path",
                )?);
                let source = verified_source_path(&source, &file.artifact_content_sha256)?;
                insert_resolved(
                    &mut files,
                    &file.destination,
                    ResolvedFile {
                        source: MaterializationSource::Path(source),
                        digest: file.artifact_content_sha256.clone(),
                        executable: file.executable,
                    },
                )?;
            }
        }
        let site_roots = resolver.site_package_roots()?;
        let mut complete_site_roots = Vec::new();
        for site_root in &site_roots {
            if distribution.launch.record_closures.iter().all(|closure| {
                locate_record_closure(closure, std::slice::from_ref(site_root)).is_ok()
            }) {
                complete_site_roots.push(site_root.clone());
            }
        }
        ensure!(
            complete_site_roots.len() == 1,
            "stock evaluator closure resolved to {} complete Python environments",
            complete_site_roots.len()
        );
        let site_roots = complete_site_roots;
        for closure in &distribution.launch.record_closures {
            let overlay = distribution
                .launch
                .metadata_overlays
                .iter()
                .find(|overlay| {
                    normalize_distribution_name(&overlay.distribution)
                        == normalize_distribution_name(&closure.distribution)
                        && overlay.version == closure.version
                });
            resolve_record_closure(closure, overlay, &site_roots, &mut files)?;
        }
        for file in &distribution.launch.embedded_files {
            let content: Arc<[u8]> = decode_embedded(file)?.into();
            insert_resolved(
                &mut files,
                &file.destination,
                ResolvedFile {
                    source: MaterializationSource::Bytes(content),
                    digest: file.artifact_content_sha256.clone(),
                    executable: file.executable,
                },
            )?;
        }
        for overlay in &distribution.launch.metadata_overlays {
            for file in &overlay.replacement_files {
                let content: Arc<[u8]> = decode_embedded(file)?.into();
                insert_resolved(
                    &mut files,
                    &file.destination,
                    ResolvedFile {
                        source: MaterializationSource::Bytes(content),
                        digest: file.artifact_content_sha256.clone(),
                        executable: file.executable,
                    },
                )?;
            }
        }
        let closure_digest = logical_closure_sha256(&files);
        ensure!(
            closure_digest == distribution.launch_closure_sha256,
            "resolved stock evaluator closure digest drifted"
        );
        ensure!(
            files.contains_key(PROGRAM),
            "worker program is absent from closure"
        );
        Ok(Self { files })
    }

    fn materialize(
        &self,
        root: &Path,
        distribution: &StockDistribution,
    ) -> Result<accuracy::AttestedWorkerLaunch> {
        for (destination, resolved) in &self.files {
            let destination_path = strict_relative_path(destination, "materialized destination")?;
            let target = root.join(&destination_path);
            let parent = target
                .parent()
                .ok_or_else(|| anyhow!("materialized destination has no parent"))?;
            create_secure_directories(root, parent)?;
            let content = match &resolved.source {
                MaterializationSource::Path(path) => read_verified_source(path, &resolved.digest)?,
                MaterializationSource::Bytes(content) => content.to_vec(),
            };
            ensure!(
                accuracy::artifact_content_sha256(&content) == resolved.digest,
                "materialized source digest drifted for {destination:?}"
            );
            let mut output = OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(&target)
                .with_context(|| format!("creating worker-root file {}", target.display()))?;
            output
                .write_all(&content)
                .with_context(|| format!("writing worker-root file {}", target.display()))?;
            output
                .sync_all()
                .with_context(|| format!("syncing worker-root file {}", target.display()))?;
            set_file_mode(&target, if resolved.executable { 0o555 } else { 0o444 })?;
        }
        for relative in ROOTFS_MOUNTPOINTS {
            let directory = root.join(strict_relative_path(relative, "rootfs mountpoint")?);
            create_secure_directories(root, &directory)?;
            ensure_directory_empty(&directory)?;
            set_file_mode(&directory, 0o555)?;
        }
        preflight_materialized_root(root, &self.files)?;
        let closure = self
            .files
            .iter()
            .map(|(relative, file)| accuracy::LaunchClosureFile {
                path: root.join(relative),
                artifact_content_sha256: file.digest.clone(),
            })
            .collect();
        let launch = accuracy::AttestedWorkerLaunch {
            distribution_id: accuracy::EvaluationDistributionId::new(&distribution.distribution_id)
                .map_err(|error| anyhow!(error.to_string()))?,
            program: root.join(PROGRAM),
            args: distribution
                .launch
                .args
                .iter()
                .map(OsString::from)
                .collect(),
            environment: distribution
                .launch
                .environment
                .iter()
                .map(|(key, value)| (OsString::from(key), OsString::from(value)))
                .collect(),
            current_dir: root.join(CURRENT_DIR),
            worker_root: root.to_path_buf(),
            closure,
        };
        launch
            .validate()
            .map_err(|error| anyhow!(error.to_string()))?;
        Ok(launch)
    }
}

fn resolve_record_closure(
    closure: &RecordClosure,
    overlay: Option<&MetadataOverlay>,
    site_roots: &[PathBuf],
    files: &mut BTreeMap<String, ResolvedFile>,
) -> Result<()> {
    let (site_root, record_path, record_bytes) = locate_record_closure(closure, site_roots)
        .with_context(|| {
            format!(
                "resolving RECORD closure {} {}",
                closure.distribution, closure.version
            )
        })?;
    let omitted = closure.omitted_paths.iter().collect::<BTreeSet<_>>();
    let rows = parse_record_rows(&record_bytes)?;
    if let Some(overlay) = overlay {
        verify_source_overlay_image(overlay, &site_root, &record_bytes, &rows)?;
    }
    let mut row_paths = BTreeSet::new();
    for (relative, encoded_digest, encoded_size) in rows {
        ensure!(
            row_paths.insert(relative.clone()),
            "duplicate RECORD row {relative:?}"
        );
        if omitted.contains(&relative) {
            continue;
        }
        validate_record_relative(&relative)?;
        let source = site_root.join(Path::new(&relative));
        let expected = if encoded_digest.is_empty() {
            ensure!(
                source.canonicalize().ok().as_deref() == record_path.canonicalize().ok().as_deref(),
                "only the RECORD file may omit its own digest"
            );
            closure.record_sha256.clone()
        } else {
            decode_record_digest(&encoded_digest)?
        };
        let source = verified_source_path(&source, &expected)?;
        let environment_root = site_root
            .ancestors()
            .nth(3)
            .ok_or_else(|| anyhow!("site-packages root has no environment ancestor"))?
            .canonicalize()
            .context("canonicalizing Python environment root")?;
        ensure!(
            source.starts_with(&environment_root),
            "RECORD source escaped its Python environment root"
        );
        let metadata = source
            .metadata()
            .with_context(|| format!("inspecting RECORD source {}", source.display()))?;
        if !encoded_size.is_empty() {
            let expected_size: u64 = encoded_size
                .parse()
                .with_context(|| format!("invalid RECORD size for {relative:?}"))?;
            ensure!(
                metadata.len() == expected_size,
                "RECORD size drift for {relative:?}"
            );
        }
        let destination = logical_join(&closure.destination_prefix, &relative)?;
        insert_resolved(
            files,
            &destination,
            ResolvedFile {
                source: MaterializationSource::Path(source.clone()),
                digest: expected,
                executable: is_executable(&source)?,
            },
        )?;
    }
    ensure!(
        omitted.iter().all(|path| row_paths.contains(*path)),
        "RECORD omitted-path policy named a missing row"
    );
    Ok(())
}

fn verify_source_overlay_image(
    overlay: &MetadataOverlay,
    site_root: &Path,
    upstream_record: &[u8],
    rows: &[(String, String, String)],
) -> Result<()> {
    ensure!(
        accuracy::artifact_content_sha256(upstream_record) == overlay.upstream_record_sha256,
        "source overlay upstream RECORD digest drifted"
    );
    let dist_info = dist_info_prefix(&overlay.distribution, &overlay.version);
    let metadata_relative = format!("{dist_info}/METADATA");
    let metadata_replacement = replacement_file(
        &overlay.replacement_files,
        &format!("{SITE_PACKAGES_DESTINATION}/{metadata_relative}"),
    )
    .ok_or_else(|| anyhow!("source overlay omitted rebuilt METADATA"))?;
    ensure!(
        read_file(&site_root.join(&metadata_relative))? == decode_embedded(metadata_replacement)?,
        "source overlay changed upstream package METADATA"
    );
    let import_package = overlay.distribution.replace('-', "_");
    let package_prefix = format!("{import_package}/");
    let mut semantic = BTreeMap::new();
    for (relative, encoded_digest, encoded_size) in rows {
        let Some(package_relative) = relative.strip_prefix(&package_prefix) else {
            continue;
        };
        if !is_semantic_source_path(package_relative) {
            continue;
        }
        validate_semantic_relative_path(package_relative, "upstream semantic source path")?;
        let source = site_root.join(relative);
        let metadata = std::fs::symlink_metadata(&source)
            .with_context(|| format!("inspecting upstream source {relative:?}"))?;
        ensure!(
            metadata.file_type().is_file() && !metadata.file_type().is_symlink(),
            "upstream semantic source is not a regular non-symlink file"
        );
        let expected = decode_record_digest(encoded_digest)?;
        let content = read_verified_source(&source, &expected)?;
        let expected_size: u64 = encoded_size
            .parse()
            .with_context(|| format!("invalid RECORD size for {relative:?}"))?;
        ensure!(
            content.len() as u64 == expected_size,
            "upstream semantic source size drifted"
        );
        ensure!(
            semantic
                .insert(package_relative.to_owned(), content)
                .is_none(),
            "duplicate upstream semantic source path"
        );
    }
    for excluded in &overlay.base_source.excluded_relative_paths {
        ensure!(
            semantic.remove(excluded).is_some(),
            "source-tree exclusion named a missing semantic file"
        );
    }
    for restored in &overlay.base_source.restored_files {
        let destination = format!(
            "{SITE_PACKAGES_DESTINATION}/{import_package}/{}",
            restored.relative_path
        );
        let file = replacement_file(&overlay.replacement_files, &destination)
            .ok_or_else(|| anyhow!("restored base source content is absent"))?;
        let content = decode_embedded(file)?;
        ensure!(
            semantic
                .insert(restored.relative_path.clone(), content)
                .is_none(),
            "restored base source collided with an upstream file"
        );
    }
    ensure!(
        semantic_source_tree_sha256(&semantic) == overlay.base_source.source_tree_sha256,
        "base semantic source-tree digest drifted"
    );
    for target in overlay.overlays.iter().flat_map(|overlay| &overlay.targets) {
        match &target.base_content_sha256 {
            Some(expected) => {
                let base = semantic
                    .get(&target.relative_path)
                    .ok_or_else(|| anyhow!("source overlay existing target was absent"))?;
                ensure!(
                    accuracy::artifact_content_sha256(base) == *expected,
                    "source overlay base-content digest drifted"
                );
            }
            None => ensure!(
                !semantic.contains_key(&target.relative_path),
                "source overlay new target already existed in the base tree"
            ),
        }
        let destination = format!(
            "{SITE_PACKAGES_DESTINATION}/{import_package}/{}",
            target.relative_path
        );
        let file = replacement_file(&overlay.replacement_files, &destination)
            .ok_or_else(|| anyhow!("source overlay target content is absent"))?;
        let content = decode_embedded(file)?;
        ensure!(
            accuracy::artifact_content_sha256(&content) == target.effective_content_sha256,
            "source overlay effective-content digest drifted"
        );
        semantic.insert(target.relative_path.clone(), content);
    }
    ensure!(
        semantic_source_tree_sha256(&semantic) == overlay.effective_source_tree_sha256,
        "effective semantic source-tree digest drifted"
    );
    verify_rebuilt_record(overlay, rows)?;
    Ok(())
}

fn is_semantic_source_path(relative: &str) -> bool {
    !relative.split('/').any(|part| part == "__pycache__")
        && Path::new(relative)
            .extension()
            .and_then(|extension| extension.to_str())
            .is_some_and(|extension| matches!(extension, "py" | "json" | "toml" | "yaml" | "yml"))
}

fn semantic_source_tree_sha256(files: &BTreeMap<String, Vec<u8>>) -> String {
    let mut framed = Vec::new();
    for (relative, content) in files {
        let path = relative.as_bytes();
        framed.extend_from_slice(&(path.len() as u64).to_be_bytes());
        framed.extend_from_slice(path);
        framed.extend_from_slice(&(content.len() as u64).to_be_bytes());
        framed.extend_from_slice(content);
    }
    accuracy::artifact_content_sha256(&framed)
}

fn verify_rebuilt_record(
    overlay: &MetadataOverlay,
    rows: &[(String, String, String)],
) -> Result<()> {
    let omitted = overlay.omitted_paths.iter().collect::<BTreeSet<_>>();
    let mut rebuilt = rows
        .iter()
        .filter(|(relative, _, _)| !omitted.contains(relative))
        .cloned()
        .collect::<Vec<_>>();
    let dist_info = dist_info_prefix(&overlay.distribution, &overlay.version);
    let record_relative = format!("{dist_info}/RECORD");
    for file in &overlay.replacement_files {
        let relative = file
            .destination
            .strip_prefix(&format!("{SITE_PACKAGES_DESTINATION}/"))
            .ok_or_else(|| anyhow!("source replacement escaped site-packages"))?;
        if relative == record_relative {
            continue;
        }
        let digest = sha256_record_field(&file.artifact_content_sha256)?;
        let size = decode_embedded(file)?.len().to_string();
        rebuilt.push((relative.to_owned(), digest, size));
    }
    rebuilt.push((record_relative.clone(), String::new(), String::new()));
    rebuilt.sort_by(|left, right| left.0.as_bytes().cmp(right.0.as_bytes()));
    ensure!(
        rebuilt.windows(2).all(|pair| pair[0].0 != pair[1].0),
        "rebuilt source-overlay RECORD has duplicate paths"
    );
    let mut writer = csv::WriterBuilder::new()
        .has_headers(false)
        .terminator(csv::Terminator::Any(b'\n'))
        .from_writer(Vec::new());
    for row in rebuilt {
        writer
            .write_record([row.0, row.1, row.2])
            .context("encoding rebuilt source-overlay RECORD")?;
    }
    let expected = writer
        .into_inner()
        .context("finishing rebuilt source-overlay RECORD")?;
    let actual_file = replacement_file(
        &overlay.replacement_files,
        &format!("{SITE_PACKAGES_DESTINATION}/{record_relative}"),
    )
    .ok_or_else(|| anyhow!("source overlay omitted rebuilt RECORD"))?;
    ensure!(
        decode_embedded(actual_file)? == expected,
        "rebuilt source-overlay RECORD bytes drifted"
    );
    Ok(())
}

fn sha256_record_field(value: &str) -> Result<String> {
    validate_sha256(value, "RECORD replacement digest")?;
    let mut bytes = Vec::with_capacity(32);
    for pair in value.as_bytes().chunks_exact(2) {
        let encoded = std::str::from_utf8(pair).context("decoding replacement SHA-256")?;
        bytes.push(u8::from_str_radix(encoded, 16).context("decoding replacement SHA-256")?);
    }
    Ok(format!("sha256={}", URL_SAFE_NO_PAD.encode(bytes)))
}

fn locate_record_closure(
    closure: &RecordClosure,
    site_roots: &[PathBuf],
) -> Result<(PathBuf, PathBuf, Vec<u8>)> {
    let expected_name = normalize_distribution_name(&closure.distribution);
    let mut matches = Vec::new();
    for site_root in site_roots {
        for entry in std::fs::read_dir(site_root)
            .with_context(|| format!("enumerating site-packages {}", site_root.display()))?
        {
            let entry = entry.context("reading site-packages entry")?;
            let path = entry.path();
            if !entry.file_name().to_string_lossy().ends_with(".dist-info") {
                continue;
            }
            let metadata = std::fs::symlink_metadata(&path)
                .with_context(|| format!("inspecting dist-info {}", path.display()))?;
            if !metadata.file_type().is_dir() || metadata.file_type().is_symlink() {
                continue;
            }
            let metadata_bytes = match std::fs::read(path.join("METADATA")) {
                Ok(bytes) => bytes,
                Err(_) => continue,
            };
            let (name, version) = metadata_identity(&metadata_bytes)?;
            if normalize_distribution_name(&name) != expected_name || version != closure.version {
                continue;
            }
            let record_path = path.join("RECORD");
            let record_bytes = std::fs::read(&record_path)
                .with_context(|| format!("reading RECORD {}", record_path.display()))?;
            ensure!(
                accuracy::artifact_content_sha256(&record_bytes) == closure.record_sha256,
                "installed RECORD digest drift for {}",
                closure.distribution
            );
            matches.push((site_root.clone(), record_path, record_bytes));
        }
    }
    ensure!(
        matches.len() == 1,
        "distribution {} {} resolved to {} installed RECORDs",
        closure.distribution,
        closure.version,
        matches.len()
    );
    Ok(matches.remove(0))
}

fn metadata_identity(bytes: &[u8]) -> Result<(String, String)> {
    let text = std::str::from_utf8(bytes).context("dist-info METADATA was not UTF-8")?;
    let mut name = None;
    let mut version = None;
    for line in text.lines().take_while(|line| !line.is_empty()) {
        if let Some(value) = line.strip_prefix("Name: ") {
            ensure!(
                name.replace(value.to_string()).is_none(),
                "duplicate METADATA Name"
            );
        }
        if let Some(value) = line.strip_prefix("Version: ") {
            ensure!(
                version.replace(value.to_string()).is_none(),
                "duplicate METADATA Version"
            );
        }
    }
    Ok((
        name.ok_or_else(|| anyhow!("METADATA omitted Name"))?,
        version.ok_or_else(|| anyhow!("METADATA omitted Version"))?,
    ))
}

fn parse_record_rows(bytes: &[u8]) -> Result<Vec<(String, String, String)>> {
    let mut reader = csv::ReaderBuilder::new()
        .has_headers(false)
        .flexible(false)
        .from_reader(bytes);
    let mut rows = Vec::new();
    for row in reader.records() {
        let row = row.context("decoding distribution RECORD CSV")?;
        ensure!(
            row.len() == 3,
            "distribution RECORD row must have three fields"
        );
        let relative = row.get(0).expect("length checked").to_string();
        validate_record_relative(&relative)?;
        rows.push((
            relative,
            row.get(1).expect("length checked").to_string(),
            row.get(2).expect("length checked").to_string(),
        ));
    }
    ensure!(!rows.is_empty(), "distribution RECORD is empty");
    Ok(rows)
}

fn decode_record_digest(encoded: &str) -> Result<String> {
    let payload = encoded
        .strip_prefix("sha256=")
        .ok_or_else(|| anyhow!("RECORD digest does not use sha256"))?;
    let bytes = URL_SAFE_NO_PAD
        .decode(payload)
        .context("decoding RECORD SHA-256")?;
    ensure!(bytes.len() == 32, "RECORD SHA-256 has the wrong length");
    Ok(bytes.iter().map(|byte| format!("{byte:02x}")).collect())
}

fn decode_embedded(file: &EmbeddedFile) -> Result<Vec<u8>> {
    BASE64_STANDARD
        .decode(&file.content_base64)
        .with_context(|| format!("decoding embedded resource {:?}", file.resource))
}

fn insert_resolved(
    files: &mut BTreeMap<String, ResolvedFile>,
    destination: &str,
    resolved: ResolvedFile,
) -> Result<()> {
    let destination = path_to_logical(&strict_relative_path(
        destination,
        "launch closure destination",
    )?)?;
    ensure!(
        files.insert(destination.clone(), resolved).is_none(),
        "duplicate launch closure destination {destination:?}"
    );
    Ok(())
}

fn logical_closure_sha256(files: &BTreeMap<String, ResolvedFile>) -> String {
    let mut bytes = Vec::new();
    for (path, file) in files {
        bytes.extend_from_slice(path.as_bytes());
        bytes.push(0);
        bytes.extend_from_slice(file.digest.as_bytes());
        bytes.push(b'\n');
    }
    accuracy::artifact_content_sha256(&bytes)
}

fn preflight_materialized_root(
    root: &Path,
    expected: &BTreeMap<String, ResolvedFile>,
) -> Result<()> {
    let root = root
        .canonicalize()
        .with_context(|| format!("canonicalizing worker root {}", root.display()))?;
    let mut actual = BTreeMap::new();
    let mut pending = vec![root.clone()];
    while let Some(directory) = pending.pop() {
        for entry in std::fs::read_dir(&directory)
            .with_context(|| format!("enumerating worker root {}", directory.display()))?
        {
            let entry = entry.context("reading worker-root entry")?;
            let path = entry.path();
            let metadata = std::fs::symlink_metadata(&path)
                .with_context(|| format!("inspecting worker-root entry {}", path.display()))?;
            if metadata.file_type().is_dir() && !metadata.file_type().is_symlink() {
                pending.push(path);
                continue;
            }
            ensure!(
                metadata.file_type().is_file() && !metadata.file_type().is_symlink(),
                "worker root contains a symlink or special file"
            );
            #[cfg(unix)]
            {
                use std::os::unix::fs::MetadataExt as _;
                ensure!(metadata.nlink() == 1, "worker-root file is a hard link");
            }
            let relative = path
                .strip_prefix(&root)
                .context("worker-root entry escaped root")?;
            let relative = path_to_logical(relative)?;
            actual.insert(
                relative,
                ResolvedFile {
                    source: MaterializationSource::Path(path.clone()),
                    digest: accuracy::artifact_content_sha256(&std::fs::read(&path)?),
                    executable: is_executable(&path)?,
                },
            );
        }
    }
    ensure!(
        actual.len() == expected.len()
            && actual.iter().all(|(path, file)| {
                expected.get(path).is_some_and(|expected| {
                    expected.digest == file.digest && expected.executable == file.executable
                })
            }),
        "materialized rootfs file inventory drifted"
    );
    ensure!(
        logical_closure_sha256(&actual) == logical_closure_sha256(expected),
        "materialized rootfs closure digest drifted"
    );
    for relative in ROOTFS_MOUNTPOINTS {
        ensure_directory_empty(&root.join(relative))?;
    }
    Ok(())
}

fn create_secure_directories(root: &Path, destination: &Path) -> Result<()> {
    let relative = destination
        .strip_prefix(root)
        .context("worker-root directory escaped root")?;
    let mut current = root.to_path_buf();
    for component in relative.components() {
        let Component::Normal(component) = component else {
            bail!("worker-root directory contained a non-normal component");
        };
        current.push(component);
        match std::fs::symlink_metadata(&current) {
            Ok(metadata) => ensure!(
                metadata.file_type().is_dir() && !metadata.file_type().is_symlink(),
                "worker-root parent is not a real directory"
            ),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                std::fs::create_dir(&current).with_context(|| {
                    format!("creating worker-root directory {}", current.display())
                })?;
                set_file_mode(&current, 0o755)?;
            }
            Err(error) => return Err(error.into()),
        }
    }
    Ok(())
}

fn ensure_directory_empty(path: &Path) -> Result<()> {
    let metadata = std::fs::symlink_metadata(path)
        .with_context(|| format!("inspecting rootfs mountpoint {}", path.display()))?;
    ensure!(
        metadata.file_type().is_dir() && !metadata.file_type().is_symlink(),
        "rootfs mountpoint is not a real directory"
    );
    ensure!(
        std::fs::read_dir(path)
            .with_context(|| format!("enumerating rootfs mountpoint {}", path.display()))?
            .next()
            .is_none(),
        "rootfs mountpoint {} is not empty",
        path.display()
    );
    Ok(())
}

fn verified_source_path(path: &Path, expected_digest: &str) -> Result<PathBuf> {
    let canonical = path
        .canonicalize()
        .with_context(|| format!("canonicalizing closure source {}", path.display()))?;
    verify_regular_file_digest(&canonical, expected_digest)?;
    Ok(canonical)
}

fn verify_regular_file_digest(path: &Path, expected_digest: &str) -> Result<()> {
    let metadata = std::fs::symlink_metadata(path)
        .with_context(|| format!("inspecting closure source {}", path.display()))?;
    ensure!(
        metadata.file_type().is_file() && !metadata.file_type().is_symlink(),
        "closure source {} is not a regular non-symlink file",
        path.display()
    );
    let content = read_file(path)?;
    ensure!(
        accuracy::artifact_content_sha256(&content) == expected_digest,
        "closure source digest drift for {}",
        path.display()
    );
    Ok(())
}

fn read_verified_source(path: &Path, expected_digest: &str) -> Result<Vec<u8>> {
    verify_regular_file_digest(path, expected_digest)?;
    read_file(path)
}

fn read_file(path: &Path) -> Result<Vec<u8>> {
    let mut input =
        File::open(path).with_context(|| format!("opening closure source {}", path.display()))?;
    let metadata = input
        .metadata()
        .with_context(|| format!("inspecting opened closure source {}", path.display()))?;
    ensure!(metadata.is_file(), "opened closure source is not a file");
    let mut content = Vec::new();
    input
        .read_to_end(&mut content)
        .with_context(|| format!("reading closure source {}", path.display()))?;
    Ok(content)
}

fn is_executable(path: &Path) -> Result<bool> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        Ok(path
            .metadata()
            .with_context(|| format!("inspecting executable bit {}", path.display()))?
            .permissions()
            .mode()
            & 0o111
            != 0)
    }
    #[cfg(not(unix))]
    {
        let _ = path;
        Ok(false)
    }
}

fn set_file_mode(path: &Path, mode: u32) -> Result<()> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        std::fs::set_permissions(path, std::fs::Permissions::from_mode(mode))
            .with_context(|| format!("setting worker-root mode for {}", path.display()))?;
    }
    #[cfg(not(unix))]
    {
        let _ = (path, mode);
    }
    Ok(())
}

fn strict_relative_path(value: &str, field: &str) -> Result<PathBuf> {
    ensure!(
        !value.is_empty()
            && !value.contains('\\')
            && !value.contains('\0')
            && value
                .split('/')
                .all(|component| !matches!(component, "" | "." | "..")),
        "{field} is not a canonical logical path"
    );
    let path = Path::new(value);
    ensure!(!path.is_absolute(), "{field} must be relative");
    ensure!(
        path.components()
            .all(|component| matches!(component, Component::Normal(_))),
        "{field} must contain only normal components"
    );
    Ok(path.to_path_buf())
}

fn validate_record_relative(value: &str) -> Result<()> {
    ensure!(
        !value.is_empty()
            && !value.starts_with('/')
            && !value.contains('\\')
            && !value.contains('\0'),
        "RECORD path is not relative"
    );
    ensure!(
        value
            .split('/')
            .any(|part| !matches!(part, "" | "." | "..")),
        "RECORD path normalized empty"
    );
    Ok(())
}

fn logical_join(prefix: &str, relative: &str) -> Result<String> {
    let mut parts = prefix
        .split('/')
        .filter(|part| !part.is_empty() && *part != ".")
        .map(str::to_owned)
        .collect::<Vec<_>>();
    for part in relative.split('/') {
        match part {
            "" | "." => {}
            ".." => {
                ensure!(parts.pop().is_some(), "logical destination escaped root");
            }
            value => parts.push(value.to_owned()),
        }
    }
    ensure!(!parts.is_empty(), "logical destination normalized empty");
    let output = parts.join("/");
    strict_relative_path(&output, "logical destination")?;
    Ok(output)
}

fn path_to_logical(path: &Path) -> Result<String> {
    path.to_str()
        .map(str::to_owned)
        .ok_or_else(|| anyhow!("logical path was not UTF-8"))
}

fn validate_python_identity(
    implementation: &str,
    version: &str,
    abi: &str,
    platform: &str,
) -> Result<()> {
    ensure!(
        implementation == PYTHON_IMPLEMENTATION
            && version == PYTHON_VERSION
            && abi == PYTHON_ABI
            && platform == PLATFORM,
        "stock evaluator Python identity drifted"
    );
    Ok(())
}

fn validate_sha256(value: &str, field: &str) -> Result<()> {
    ensure!(
        accuracy::is_sha256(value),
        "{field} is not a lowercase SHA-256"
    );
    Ok(())
}

fn validate_source_commit(value: &str, field: &str) -> Result<()> {
    ensure!(
        value.len() == 40
            && value
                .bytes()
                .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte)),
        "{field} is not an immutable lowercase Git commit"
    );
    Ok(())
}

fn validate_identity_components(
    components: &[accuracy::EvaluationIdentityComponent],
) -> Result<()> {
    ensure!(
        !components.is_empty(),
        "stock evaluator has no identity components"
    );
    let mut names = BTreeSet::new();
    for component in components {
        validate_open_manifest_id(&component.name, "evaluation identity component name")?;
        ensure!(
            !component.version.trim().is_empty() && component.version.trim() == component.version,
            "evaluation identity component version is invalid"
        );
        validate_sha256(
            &component.source_sha256,
            "evaluation identity component source",
        )?;
        ensure!(
            names.insert(normalize_distribution_name(&component.name)),
            "duplicate evaluation identity component {:?}",
            component.name
        );
        if component.overlays.is_empty() {
            ensure!(
                component.source_commit.is_none()
                    && component.base_source_sha256.is_none()
                    && component.overlay_policy.is_none(),
                "evaluation identity component declared incomplete overlay identity"
            );
            continue;
        }
        validate_source_commit(
            component
                .source_commit
                .as_deref()
                .ok_or_else(|| anyhow!("overlaid identity component omitted base commit"))?,
            "identity component base commit",
        )?;
        validate_sha256(
            component
                .base_source_sha256
                .as_deref()
                .ok_or_else(|| anyhow!("overlaid identity component omitted base digest"))?,
            "identity component base source",
        )?;
        ensure!(
            component.overlay_policy.as_deref() == Some(SOURCE_OVERLAY_POLICY),
            "identity component source overlay policy drifted"
        );
        let mut overlays = BTreeSet::new();
        for overlay in &component.overlays {
            validate_open_manifest_id(&overlay.overlay_id, "identity source overlay ID")?;
            validate_sha256(
                &overlay.artifact_content_sha256,
                "identity source overlay digest",
            )?;
            ensure!(
                overlays.insert(&overlay.overlay_id),
                "duplicate identity source overlay ID"
            );
        }
    }
    Ok(())
}

fn validate_semantic_relative_path(value: &str, field: &str) -> Result<()> {
    let path = strict_relative_path(value, field)?;
    ensure!(
        !path
            .components()
            .any(|component| component.as_os_str() == "__pycache__")
            && path
                .extension()
                .and_then(|extension| extension.to_str())
                .is_some_and(|extension| {
                    matches!(extension, "py" | "json" | "toml" | "yaml" | "yml")
                }),
        "{field} is outside the semantic source-tree domain"
    );
    Ok(())
}

fn ensure_strict_utf8_order(values: &[String], field: &str) -> Result<()> {
    for pair in values.windows(2) {
        ensure!(
            pair[0].as_bytes() < pair[1].as_bytes(),
            "{field} must be unique and sorted by UTF-8 bytes"
        );
    }
    Ok(())
}

fn ensure_utf8_after(prior: Option<&str>, value: &str, field: &str) -> Result<()> {
    ensure!(
        prior.is_none_or(|prior| prior.as_bytes() < value.as_bytes()),
        "{field} must be unique and sorted by UTF-8 bytes"
    );
    Ok(())
}

fn validate_open_manifest_id(value: &str, field: &str) -> Result<()> {
    ensure!(
        !value.is_empty()
            && value.bytes().all(|byte| {
                byte.is_ascii_lowercase()
                    || byte.is_ascii_digit()
                    || matches!(byte, b'_' | b'-' | b'.')
            }),
        "{field} is invalid"
    );
    Ok(())
}

fn normalize_distribution_name(value: &str) -> String {
    let mut output = String::new();
    let mut separator = false;
    for character in value.chars() {
        if matches!(character, '-' | '_' | '.') {
            separator = !output.is_empty();
        } else {
            if separator {
                output.push('-');
                separator = false;
            }
            output.extend(character.to_lowercase());
        }
    }
    output
}

struct MaterializedRootGuard {
    root: Option<PathBuf>,
}

impl fmt::Debug for MaterializedRootGuard {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("MaterializedRootGuard")
            .field("active", &self.root.is_some())
            .finish()
    }
}

impl MaterializedRootGuard {
    fn create(parent: &Path) -> Result<Self> {
        let parent = parent
            .canonicalize()
            .with_context(|| format!("canonicalizing worker-root parent {}", parent.display()))?;
        for _ in 0..8 {
            let root = parent.join(format!("worker-root-{}", Uuid::new_v4().simple()));
            match std::fs::create_dir(&root) {
                Ok(()) => {
                    set_file_mode(&root, 0o700)?;
                    return Ok(Self { root: Some(root) });
                }
                Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => continue,
                Err(error) => return Err(error.into()),
            }
        }
        bail!("failed to allocate an exclusive evaluator worker root")
    }

    fn path(&self) -> &Path {
        self.root.as_deref().expect("active materialized root")
    }

    fn after_worker_shutdown(&self) {
        // Quiescence is proven by the delegated provider. The immutable root
        // intentionally remains until report commit binds its provenance.
    }

    fn after_artifacts_sealed(&self) {
        // Artifact sealing also precedes report commit; keep the root alive.
    }

    fn after_report_commit(&mut self) -> Result<()> {
        self.cleanup()
    }

    fn cleanup(&mut self) -> Result<()> {
        let Some(root) = self.root.as_ref() else {
            return Ok(());
        };
        ensure!(
            root.file_name()
                .and_then(|name| name.to_str())
                .is_some_and(|name| name.starts_with("worker-root-")),
            "refusing to clean an unrecognized evaluator root"
        );
        std::fs::remove_dir_all(root)
            .with_context(|| format!("removing materialized evaluator root {}", root.display()))?;
        ensure!(
            !root.exists(),
            "materialized evaluator root remained after cleanup"
        );
        self.root = None;
        Ok(())
    }
}

impl Drop for MaterializedRootGuard {
    fn drop(&mut self) {
        if let Err(error) = self.cleanup() {
            tracing::error!(error = %error, "failed to clean materialized evaluator root on drop");
        }
    }
}

struct StockPreparedLaunch {
    distribution_id: accuracy::EvaluationDistributionId,
    prelaunch_context_sha256: String,
    isolation_evidence: accuracy::EvaluatorIsolationEvidence,
    inner_launcher: Arc<accuracy::SupervisedEvaluationProviderLauncher>,
    inner: Box<dyn accuracy::PreparedEvaluationProviderLaunch>,
    root: MaterializedRootGuard,
    authority: Arc<()>,
}

impl fmt::Debug for StockPreparedLaunch {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("StockPreparedLaunch")
            .field("distribution_id", &self.distribution_id)
            .field("root", &self.root)
            .finish_non_exhaustive()
    }
}

impl accuracy::PreparedEvaluationProviderLaunch for StockPreparedLaunch {
    fn distribution_id(&self) -> &accuracy::EvaluationDistributionId {
        &self.distribution_id
    }

    fn prelaunch_context_sha256(&self) -> &str {
        &self.prelaunch_context_sha256
    }

    fn isolation_evidence(&self) -> &accuracy::EvaluatorIsolationEvidence {
        &self.isolation_evidence
    }

    fn into_any(self: Box<Self>) -> Box<dyn Any + Send> {
        self
    }
}

struct StockEvaluationProviderLauncher {
    manifest: Arc<StockDistributionManifest>,
    distribution_id: accuracy::EvaluationDistributionId,
    sources: Arc<dyn StockClosureSourceResolver>,
    authority: Arc<()>,
}

impl fmt::Debug for StockEvaluationProviderLauncher {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("StockEvaluationProviderLauncher")
            .field("distribution_id", &self.distribution_id)
            .finish_non_exhaustive()
    }
}

impl StockEvaluationProviderLauncher {
    fn new(
        manifest: Arc<StockDistributionManifest>,
        distribution_id: accuracy::EvaluationDistributionId,
    ) -> Self {
        Self {
            manifest,
            distribution_id,
            sources: Arc::new(EnvironmentStockClosureSourceResolver),
            authority: Arc::new(()),
        }
    }

    fn entry(&self) -> Result<&StockDistribution> {
        self.manifest.distribution(&self.distribution_id)
    }

    fn validate_descriptor(
        &self,
        descriptor: &accuracy::EvaluationProviderDescriptor,
        distribution: &accuracy::EvaluationDistributionDescriptor,
    ) -> Result<()> {
        let entry = self.entry()?;
        ensure!(
            descriptor.provider_id.as_str() == entry.provider_id
                && descriptor.config_schema_version == entry.config_schema_version
                && descriptor.config_schema_sha256 == entry.config_schema_sha256
                && distribution == &entry.descriptor()?,
            "stock provider descriptor drifted from embedded manifest"
        );
        Ok(())
    }
}

#[async_trait(?Send)]
impl accuracy::EvaluationProviderLauncher for StockEvaluationProviderLauncher {
    fn check_distribution_available(
        &self,
        distribution: &accuracy::EvaluationDistributionDescriptor,
    ) -> std::result::Result<(), accuracy::EvaluationProviderError> {
        let entry = self
            .entry()
            .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))?;
        if distribution
            != &entry
                .descriptor()
                .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))?
        {
            return Err(accuracy::EvaluationProviderError::FactoryMismatch(
                "stock distribution descriptor drifted from embedded manifest".to_owned(),
            ));
        }
        ResolvedLaunchClosure::resolve(self.manifest.as_ref(), entry, self.sources.as_ref())
            .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))?;
        entry
            .isolation
            .implementation()
            .and_then(|isolation| {
                isolation
                    .check_available()
                    .map_err(|error| anyhow!(error.to_string()))
            })
            .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))
    }

    fn prepare_launch(
        &self,
        descriptor: &accuracy::EvaluationProviderDescriptor,
        distribution: &accuracy::EvaluationDistributionDescriptor,
        context: accuracy::ProviderLaunchContext,
    ) -> std::result::Result<
        Box<dyn accuracy::PreparedEvaluationProviderLaunch>,
        accuracy::EvaluationProviderError,
    > {
        self.validate_descriptor(descriptor, distribution)
            .map_err(|error| {
                accuracy::EvaluationProviderError::FactoryMismatch(format!("{error:#}"))
            })?;
        let entry = self
            .entry()
            .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))?;
        let closure =
            ResolvedLaunchClosure::resolve(self.manifest.as_ref(), entry, self.sources.as_ref())
                .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))?;
        prepare_staging_environment(&context.staging_dir, &entry.launch)
            .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))?;
        let parent = context.staging_dir.parent().ok_or_else(|| {
            accuracy::EvaluationProviderError::Launch(
                "evaluation staging root has no parent for worker root".to_owned(),
            )
        })?;
        let root = MaterializedRootGuard::create(parent)
            .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))?;
        let launch = closure
            .materialize(root.path(), entry)
            .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))?;
        let inner_launcher = Arc::new(accuracy::SupervisedEvaluationProviderLauncher::new(
            vec![launch],
            Arc::new(accuracy::Sha256LaunchAttestor),
            entry
                .isolation
                .implementation()
                .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))?,
        )?);
        let inner = inner_launcher.prepare_launch(descriptor, distribution, context)?;
        Ok(Box::new(StockPreparedLaunch {
            distribution_id: inner.distribution_id().clone(),
            prelaunch_context_sha256: inner.prelaunch_context_sha256().to_owned(),
            isolation_evidence: inner.isolation_evidence().clone(),
            inner_launcher,
            inner,
            root,
            authority: self.authority.clone(),
        }))
    }

    async fn launch(
        &self,
        descriptor: &accuracy::EvaluationProviderDescriptor,
        config: &accuracy::ValidatedProviderConfig,
        host_binding: accuracy::EvaluationHostBinding,
        prepared: Box<dyn accuracy::PreparedEvaluationProviderLaunch>,
    ) -> std::result::Result<Box<dyn accuracy::EvaluationProvider>, accuracy::EvaluationProviderError>
    {
        let prepared = prepared
            .into_any()
            .downcast::<StockPreparedLaunch>()
            .map_err(|_| {
                accuracy::EvaluationProviderError::FactoryMismatch(
                    "stock launcher received a foreign prepared token".to_owned(),
                )
            })?;
        if !Arc::ptr_eq(&prepared.authority, &self.authority)
            || prepared.distribution_id != self.distribution_id
        {
            return Err(accuracy::EvaluationProviderError::FactoryMismatch(
                "stock prepared-launch authority drifted".to_owned(),
            ));
        }
        let StockPreparedLaunch {
            inner_launcher,
            inner,
            root,
            ..
        } = *prepared;
        let inner = inner_launcher
            .launch(descriptor, config, host_binding, inner)
            .await?;
        Ok(Box::new(MaterializedEvaluationProvider { inner, root }))
    }
}

struct MaterializedEvaluationProvider {
    inner: Box<dyn accuracy::EvaluationProvider>,
    root: MaterializedRootGuard,
}

#[async_trait(?Send)]
impl accuracy::EvaluationProvider for MaterializedEvaluationProvider {
    fn identity(&self) -> &accuracy::EvaluationWorkerIdentity {
        self.inner.identity()
    }

    fn lifecycle_state(&self) -> accuracy::EvaluationLifecycleState {
        self.inner.lifecycle_state()
    }

    fn quiescence_proof(&self) -> Option<&accuracy::IsolationQuiescenceProof> {
        self.inner.quiescence_proof()
    }

    async fn plan(
        &mut self,
        request: &accuracy::EvaluationPlanRequest,
    ) -> std::result::Result<accuracy::EvaluationPlan, accuracy::EvaluationProviderError> {
        self.inner.plan(request).await
    }

    fn install_compatibility_proxy_grant(
        &mut self,
        grant: &accuracy::ScopedProxyGrant,
    ) -> std::result::Result<(), accuracy::EvaluationProviderError> {
        self.inner.install_compatibility_proxy_grant(grant)
    }

    async fn bind_assets(
        &mut self,
        assets: &[accuracy::ResolvedEvaluationAsset],
    ) -> std::result::Result<accuracy::EvaluationIdentity, accuracy::EvaluationProviderError> {
        self.inner.bind_assets(assets).await
    }

    async fn next_units(
        &mut self,
        offset: usize,
        limit: usize,
    ) -> std::result::Result<accuracy::EvaluationUnitPage, accuracy::EvaluationProviderError> {
        self.inner.next_units(offset, limit).await
    }

    async fn instantiate_units(
        &mut self,
        requests: &[accuracy::EvaluationUnitOccurrenceRequest],
    ) -> std::result::Result<
        Vec<accuracy::EvaluationUnitOccurrence>,
        accuracy::EvaluationProviderError,
    > {
        self.inner.instantiate_units(requests).await
    }

    async fn start_units(
        &mut self,
        ids: &[accuracy::EvaluationUnitId],
    ) -> std::result::Result<(), accuracy::EvaluationProviderError> {
        self.inner.start_units(ids).await
    }

    async fn poll_events(
        &mut self,
        limit: usize,
        wait_ms: u64,
    ) -> std::result::Result<accuracy::EvaluationEventBatch, accuracy::EvaluationProviderError>
    {
        self.inner.poll_events(limit, wait_ms).await
    }

    async fn submit_host_events(
        &mut self,
        events: &[accuracy::HostOperationEvent],
    ) -> std::result::Result<(), accuracy::EvaluationProviderError> {
        self.inner.submit_host_events(events).await
    }

    async fn cancel_units(
        &mut self,
        ids: &[accuracy::EvaluationUnitId],
    ) -> std::result::Result<(), accuracy::EvaluationProviderError> {
        self.inner.cancel_units(ids).await
    }

    async fn finalize_candidate(
        &mut self,
    ) -> std::result::Result<accuracy::EvaluationFinishCandidate, accuracy::EvaluationProviderError>
    {
        self.inner.finalize_candidate().await
    }

    async fn shutdown(&mut self) -> std::result::Result<(), accuracy::EvaluationProviderError> {
        self.inner.shutdown().await?;
        self.root.after_worker_shutdown();
        Ok(())
    }

    async fn abort(&mut self) -> std::result::Result<(), accuracy::EvaluationProviderError> {
        self.inner.abort().await?;
        self.root.after_worker_shutdown();
        Ok(())
    }

    fn mark_artifacts_sealed(
        &mut self,
    ) -> std::result::Result<(), accuracy::EvaluationProviderError> {
        self.inner.mark_artifacts_sealed()?;
        self.root.after_artifacts_sealed();
        Ok(())
    }

    fn mark_report_committed(
        &mut self,
    ) -> std::result::Result<(), accuracy::EvaluationProviderError> {
        self.inner.mark_report_committed()?;
        self.root
            .after_report_commit()
            .map_err(|error| accuracy::EvaluationProviderError::Quiescence(format!("{error:#}")))
    }
}

pub(crate) struct StockEvaluationComposition {
    pub(crate) providers: Arc<accuracy::EvaluationProviderRegistry>,
    pub(crate) compatibility: Arc<dyn crate::evaluation_execution::EvaluationCompatibilityPolicy>,
    pub(crate) operation_ids: BTreeSet<String>,
}

/// Build the exact frozen provider and compatibility registries from one manifest.
pub(crate) fn stock_evaluation_composition() -> Result<StockEvaluationComposition> {
    let manifest = Arc::new(StockDistributionManifest::embedded()?);
    let compatibility_entries = manifest
        .distributions
        .iter()
        .map(|entry| {
            Ok(
                crate::evaluation_execution::EvaluationCompatibilityPolicyEntry {
                    provider_id: accuracy::EvaluationProviderId::new(&entry.provider_id)
                        .map_err(|error| anyhow!(error.to_string()))?,
                    distribution_id: accuracy::EvaluationDistributionId::new(
                        &entry.distribution_id,
                    )
                    .map_err(|error| anyhow!(error.to_string()))?,
                    dialect_ids: entry
                        .compatibility_proxy
                        .as_ref()
                        .map(|proxy| proxy.dialects.clone())
                        .unwrap_or_default(),
                    route_grants: entry
                        .compatibility_proxy
                        .as_ref()
                        .map(|proxy| proxy.routes.clone())
                        .unwrap_or_default(),
                    grant_limits: entry
                        .compatibility_proxy
                        .as_ref()
                        .map(|proxy| proxy.grant_limits),
                },
            )
        })
        .collect::<Result<Vec<_>>>()?;
    let compatibility =
        crate::evaluation_execution::stock_evaluation_compatibility_policy(compatibility_entries)?;
    let operation_ids = manifest
        .distributions
        .first()
        .expect("validated stock manifest is non-empty")
        .operations
        .iter()
        .map(|operation| operation.operation_id.clone())
        .collect();
    let mut builder = accuracy::EvaluationProviderRegistryBuilder::new();
    for entry in &manifest.distributions {
        let distribution = entry.descriptor()?;
        let public_score_projection_policy = entry.public_projection.score_policy()?;
        let public_aggregate_projection_policy = entry
            .public_projection
            .aggregate_policy(&entry.provider_id)?;
        let public_metadata_projector: Arc<dyn accuracy::PublicEvaluationMetadataProjector> =
            Arc::new(entry.public_projection.metadata_policy()?);
        let launcher: Arc<dyn accuracy::EvaluationProviderLauncher> =
            Arc::new(StockEvaluationProviderLauncher::new(
                manifest.clone(),
                distribution.distribution_id.clone(),
            ));
        let factory: Arc<dyn accuracy::EvaluationProviderFactory> = match entry.provider_id.as_str()
        {
            "nemo_evaluator" => Arc::new(
                accuracy::NemoEvaluatorProviderFactory::with_public_projection_policies(
                    vec![distribution],
                    launcher,
                    public_score_projection_policy,
                    public_aggregate_projection_policy,
                    public_metadata_projector,
                )?,
            ),
            "openbench" => Arc::new(
                accuracy::OpenBenchProviderFactory::with_public_projection_policies(
                    vec![distribution],
                    launcher,
                    public_score_projection_policy,
                    public_aggregate_projection_policy,
                    public_metadata_projector,
                )?,
            ),
            provider => bail!("unregistered stock evaluator provider {provider:?}"),
        };
        ensure!(
            factory.descriptor().config_schema_version == entry.config_schema_version
                && factory.descriptor().config_schema_sha256 == entry.config_schema_sha256
                && factory.descriptor().public_projection_schemas
                    == entry
                        .public_projection
                        .score_schemas
                        .iter()
                        .map(|score| (score.score_name.clone(), score.schema_sha256.clone()))
                        .collect::<BTreeMap<_, _>>()
                && factory.descriptor().public_aggregate_projection_schemas
                    == entry
                        .public_projection
                        .aggregate_schemas
                        .iter()
                        .map(|schema| {
                            (schema.projection_id.clone(), schema.schema_sha256.clone())
                        })
                        .collect::<BTreeMap<_, _>>()
                && factory.descriptor().public_metadata_schema_sha256
                    == entry.public_projection.metadata_schema_sha256,
            "stock provider factory schema drifted from manifest for {:?}",
            entry.provider_id
        );
        builder.register(factory)?;
    }
    Ok(StockEvaluationComposition {
        providers: Arc::new(builder.freeze()?),
        compatibility,
        operation_ids,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_manifest_is_strict_and_identity_complete() {
        let manifest = StockDistributionManifest::embedded().unwrap();
        assert_eq!(manifest.distributions.len(), 2);
        assert_eq!(
            manifest
                .distributions
                .iter()
                .map(|entry| entry.provider_id.as_str())
                .collect::<Vec<_>>(),
            ["nemo_evaluator", "openbench"]
        );
        for entry in &manifest.distributions {
            assert_eq!(entry.isolation.profile_id, STOCK_ISOLATION_PROFILE);
            assert!(entry.launch.shared_closure_ids.len() >= 2);
            assert_eq!(entry.launch.program, PROGRAM);
            assert_eq!(entry.launch.current_dir, CURRENT_DIR);
        }
    }

    #[test]
    fn manifest_rejects_unknown_fields() {
        let mut value: serde_json::Value = serde_json::from_slice(STOCK_MANIFEST_BYTES).unwrap();
        value["unexpected"] = serde_json::json!(true);
        let error = serde_json::from_value::<StockDistributionManifest>(value)
            .unwrap_err()
            .to_string();
        assert!(error.contains("unknown field"), "{error}");
    }

    fn mutated_manifest_error(mutate: impl FnOnce(&mut serde_json::Value)) -> String {
        let mut value: serde_json::Value = serde_json::from_slice(STOCK_MANIFEST_BYTES).unwrap();
        mutate(&mut value);
        let manifest: StockDistributionManifest = serde_json::from_value(value).unwrap();
        manifest.validate().unwrap_err().to_string()
    }

    #[test]
    fn manifest_rejects_non_contiguous_source_overlay_ordinals() {
        let error = mutated_manifest_error(|value| {
            value["distributions"][0]["launch"]["metadata_overlays"][0]["overlays"][0]["ordinal"] =
                serde_json::json!(7);
        });
        assert!(error.contains("ordinals"), "{error}");
    }

    #[test]
    fn manifest_rejects_source_overlay_target_escape() {
        let error = mutated_manifest_error(|value| {
            value["distributions"][0]["launch"]["metadata_overlays"][0]["overlays"][0]["targets"]
                [0]["relative_path"] = serde_json::json!("../escape.py");
        });
        assert!(error.contains("canonical logical path"), "{error}");
    }

    #[test]
    fn manifest_rejects_metadata_schema_without_executable_policy() {
        let error = mutated_manifest_error(|value| {
            value["distributions"][0]["public_projection"]["metadata_schema_sha256"] =
                serde_json::json!("a".repeat(64));
        });
        assert!(error.contains("fingerprint"), "{error}");
    }

    #[test]
    fn manifest_rejects_score_schema_without_executable_validator() {
        let error = mutated_manifest_error(|value| {
            value["distributions"][0]["public_projection"]["score_schemas"][0]["projection_id"] =
                serde_json::json!("unreviewed_projection_v1");
        });
        assert!(error.contains("unknown executable validator"), "{error}");
    }

    #[test]
    fn manifest_rejects_source_attestation_byte_drift() {
        let error = mutated_manifest_error(|value| {
            let replacements =
                value["distributions"][0]["launch"]["metadata_overlays"][0]["replacement_files"]
                    .as_array_mut()
                    .unwrap();
            let attestation = replacements
                .iter_mut()
                .find(|file| {
                    file["destination"]
                        .as_str()
                        .is_some_and(|path| path.ends_with("aiperf_source_attestation.json"))
                })
                .unwrap();
            attestation["content_base64"] = serde_json::json!(BASE64_STANDARD.encode(b"{}"));
        });
        assert!(error.contains("digest mismatch"), "{error}");
    }

    #[test]
    fn manifest_rejects_split_source_overlay_resource_identity() {
        let error = mutated_manifest_error(|value| {
            let replacements =
                value["distributions"][0]["launch"]["metadata_overlays"][0]["replacement_files"]
                    .as_array_mut()
                    .unwrap();
            let resource = replacements[1]["resource"].as_str().unwrap().to_owned();
            replacements[1]["resource"] = serde_json::json!(resource.replacen(
                "generated://source-overlay/nemo-evaluator/",
                "generated://source-overlay/nemo_evaluator/",
                1,
            ));
        });
        assert!(error.contains("multiple source identities"), "{error}");
    }

    #[test]
    fn system_closure_rejects_host_environment_paths() {
        let file = LogicalFile {
            source_relative_path: "home/user/repo/.venv/package.so".to_string(),
            destination: "home/user/repo/.venv/package.so".to_string(),
            artifact_content_sha256: "a".repeat(64),
            executable: false,
        };
        let error = validate_system_closure_file(&file).unwrap_err().to_string();
        assert!(error.contains("system closure path"), "{error}");
    }

    #[test]
    #[ignore = "requires AIPERF_EVALUATOR_PROVIDER_ROOTS with the exact audited closure"]
    fn installed_stock_source_closures_resolve_to_exact_manifest_digests() {
        let manifest = StockDistributionManifest::embedded().unwrap();
        let resolver = EnvironmentStockClosureSourceResolver;
        for distribution in &manifest.distributions {
            let closure =
                ResolvedLaunchClosure::resolve(&manifest, distribution, &resolver).unwrap();
            assert_eq!(
                logical_closure_sha256(&closure.files),
                distribution.launch_closure_sha256
            );
            assert!(closure.files.contains_key(PROGRAM));
            assert!(closure.files.contains_key("assets/gsm8k_canary.jsonl"));
        }
    }

    #[test]
    #[ignore = "requires AIPERF_EVALUATOR_PROVIDER_ROOTS with the exact audited closure"]
    fn both_stock_rootfs_images_materialize_and_pass_independent_attestation() {
        let manifest = StockDistributionManifest::embedded().unwrap();
        let resolver = EnvironmentStockClosureSourceResolver;
        let temporary = tempfile::tempdir().unwrap();
        for distribution in &manifest.distributions {
            let closure =
                ResolvedLaunchClosure::resolve(&manifest, distribution, &resolver).unwrap();
            let root = temporary.path().join(&distribution.distribution_id);
            std::fs::create_dir(&root).unwrap();
            let launch = closure.materialize(&root, distribution).unwrap();
            let descriptor = distribution.descriptor().unwrap();
            let attestation = accuracy::EvaluatorLaunchAttestor::attest(
                &accuracy::Sha256LaunchAttestor,
                &launch,
                &descriptor,
            )
            .unwrap();
            assert_eq!(
                attestation.launch_closure_sha256,
                distribution.launch_closure_sha256
            );
            for mountpoint in ROOTFS_MOUNTPOINTS {
                ensure_directory_empty(&root.join(mountpoint)).unwrap();
            }
        }
    }

    #[test]
    #[ignore = "requires AIPERF_EVALUATOR_PROVIDER_ROOTS with the exact audited closure"]
    fn stock_registry_advertises_only_attested_distributions() {
        let registry = stock_evaluation_composition().unwrap().providers;
        for (provider, distribution) in [
            ("nemo_evaluator", "nvidia_nemo_evaluator_0_4_locked"),
            ("openbench", "groq_openbench_0_5_3_inspect_0_3_141_locked"),
        ] {
            let provider = accuracy::EvaluationProviderId::new(provider).unwrap();
            let distribution = accuracy::EvaluationDistributionId::new(distribution).unwrap();
            registry
                .get(&provider)
                .unwrap()
                .check_distribution_available(&distribution)
                .unwrap();
            assert!(registry.distribution_is_available(&provider, &distribution));
        }
    }

    #[test]
    fn materialized_root_lives_through_shutdown_and_sealing_until_report_commit() {
        let temporary = tempfile::tempdir().unwrap();
        let mut guard = MaterializedRootGuard::create(temporary.path()).unwrap();
        let root = guard.path().to_path_buf();
        assert!(root.is_dir());
        guard.after_worker_shutdown();
        assert!(root.is_dir());
        guard.after_artifacts_sealed();
        assert!(root.is_dir());
        guard.after_report_commit().unwrap();
        assert!(!root.exists());
    }

    #[test]
    fn materialized_root_is_removed_on_error_drop_path() {
        let temporary = tempfile::tempdir().unwrap();
        let root = {
            let guard = MaterializedRootGuard::create(temporary.path()).unwrap();
            let root = guard.path().to_path_buf();
            assert!(root.is_dir());
            root
        };
        assert!(!root.exists());
    }
}
